//! The AAPCS64 `va_list` and the variadic entry point stubs.
//!
//! On AArch64 a `va_list` is a structure describing where the caller's
//! arguments are: the register save areas for the 8 general and 8
//! floating-point argument registers (`__gr_top`/`__vr_top` point at
//! their ends, the offsets are negative and count up to zero) and the
//! stack (`__stack`). The stubs generated by [`variadic_stub!`] spill
//! `x0`-`x7` and `q0`-`q7` and build that structure, then call the `v*`
//! implementation with it appended to the fixed arguments.
//!
//! `long double` is IEEE binary128 here; it is passed in `q` registers
//! and converted to `f64` on read.

use crate::arch::f128::{f64_to_f128, f128_to_f64};
use core::ffi::c_void;

/// `va_list` (`struct __va_list`).
#[repr(C)]
pub struct VaList {
    stack: *mut u8,
    gr_top: *mut u8,
    vr_top: *mut u8,
    gr_offs: i32,
    vr_offs: i32,
}

impl VaList {
    /// Reads the next integer or pointer argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn gp(&mut self) -> u64 {
        // SAFETY: the areas were laid out by the stub / the C compiler.
        unsafe {
            if self.gr_offs < 0 {
                let p = self.gr_top.offset(self.gr_offs as isize) as *const u64;
                self.gr_offs += 8;
                *p
            } else {
                let v = *(self.stack as *const u64);
                self.stack = self.stack.add(8);
                v
            }
        }
    }

    /// Reads the next `double` argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn fp(&mut self) -> f64 {
        // SAFETY: as in `gp`.
        unsafe {
            if self.vr_offs < 0 {
                let p = self.vr_top.offset(self.vr_offs as isize) as *const f64;
                self.vr_offs += 16;
                *p
            } else {
                let v = *(self.stack as *const f64);
                self.stack = self.stack.add(8);
                v
            }
        }
    }

    /// Reads the next `long double` (binary128) argument, converted to
    /// `f64`.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn long_double(&mut self) -> f64 {
        // SAFETY: as in `gp`; a quad occupies one full `q` slot or 16
        // aligned stack bytes.
        unsafe {
            let bits = if self.vr_offs < 0 {
                let p = self.vr_top.offset(self.vr_offs as isize) as *const u128;
                self.vr_offs += 16;
                *p
            } else {
                let p = ((self.stack as usize + 15) & !15) as *const u128;
                self.stack = (p as *mut u8).add(16);
                *p
            };
            f128_to_f64(bits)
        }
    }

    /// Reads the next pointer argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn ptr(&mut self) -> *mut c_void {
        // SAFETY: forwarded.
        unsafe { self.gp() as usize as *mut c_void }
    }
}

/// Stores `v` as a C `long double` (IEEE binary128) at `dst`.
///
/// # Safety
/// `dst` must be valid for 16 bytes.
pub unsafe fn write_long_double(dst: *mut u8, v: f64) {
    // SAFETY: caller contract.
    unsafe { (dst as *mut u128).write_unaligned(f64_to_f128(v)) }
}

/// Generates a variadic C entry point `$name` with `$fixed` fixed integer
/// arguments that calls `$target` with a `va_list` pointer in `$reg`.
#[cfg(not(test))]
macro_rules! variadic_stub {
    ($name:ident, $fixed:tt, $target:path) => {
        core::arch::global_asm!(
            concat!(".globl ", stringify!($name)),
            concat!(".type ", stringify!($name), ",%function"),
            concat!(stringify!($name), ":"),
            // Frame: 64 bytes of x0-x7, 128 bytes of q0-q7, 32 bytes of
            // va_list, 16 bytes for fp/lr.
            "stp x29, x30, [sp, #-240]!",
            "mov x29, sp",
            "stp x0, x1, [sp, #16]",
            "stp x2, x3, [sp, #32]",
            "stp x4, x5, [sp, #48]",
            "stp x6, x7, [sp, #64]",
            "stp q0, q1, [sp, #80]",
            "stp q2, q3, [sp, #112]",
            "stp q4, q5, [sp, #144]",
            "stp q6, q7, [sp, #176]",
            // va_list at sp+208: stack = caller's sp (sp+240),
            // gr_top = sp+80, vr_top = sp+208, gr_offs = -(8-fixed)*8,
            // vr_offs = -128.
            "add x9, sp, #240",
            "str x9, [sp, #208]",
            "add x9, sp, #80",
            "str x9, [sp, #216]",
            "add x9, sp, #208",
            "str x9, [sp, #224]",
            concat!("mov w9, #-((8 - ", stringify!($fixed), ") * 8)"),
            "str w9, [sp, #232]",
            "mov w9, #-128",
            "str w9, [sp, #236]",
            // The va_list parameter is argument number `fixed`.
            concat!("add x", stringify!($fixed), ", sp, #208"),
            "bl {target}",
            "ldp x29, x30, [sp], #240",
            "ret",
            concat!(".size ", stringify!($name), ", .-", stringify!($name)),
            target = sym $target,
        );
    };
}
#[cfg(not(test))]
pub(crate) use variadic_stub;

/// Two halves of a binary128 value, returned in `x0:x1`.
#[repr(C)]
pub struct F128Halves {
    /// Low 64 bits.
    pub lo: u64,
    /// High 64 bits.
    pub hi: u64,
}

/// Converts a `double` to the halves of the equal binary128 value.
pub extern "C" fn __rustlibc_f128_halves(x: f64) -> F128Halves {
    let bits = f64_to_f128(x);
    F128Halves {
        lo: bits as u64,
        hi: (bits >> 64) as u64,
    }
}

/// Defines `$name`, a function with `$target`'s arguments that returns
/// `$target`'s `double` result as a C `long double` (on AArch64 an IEEE
/// binary128 in `q0`).
macro_rules! long_double_stub {
    ($name:ident, $target:path) => {
        core::arch::global_asm!(
            concat!(".globl ", stringify!($name)),
            concat!(".type ", stringify!($name), ",%function"),
            concat!(stringify!($name), ":"),
            "stp x29, x30, [sp, #-16]!",
            "mov x29, sp",
            "bl {target}",
            "bl {halves}",
            "ldp x29, x30, [sp], #16",
            "fmov d0, x0",
            "mov v0.d[1], x1",
            "ret",
            concat!(".size ", stringify!($name), ", .-", stringify!($name)),
            target = sym $target,
            halves = sym $crate::arch::va::__rustlibc_f128_halves,
        );
    };
}
#[cfg(not(test))]
pub(crate) use long_double_stub;
